+  }
+
+  saved_conn = conn;
+  saved_mysql_available = mysql_available;
+  saved_world = world;
+  saved_top_of_world = top_of_world;
+  conn = connection;
+  mysql_available = TRUE;
+  vessel_piracy_clear_laws();
+
+  /* Offenses accumulate; the decay clock restarts with each one. */
+  vessel_add_bounty("Corr", 400);
