+void Test_vessel_shipfire_lags_on_a_miss(CuTest *tc)
+{
+  struct greyhawk_ship_data *ship = &greyhawk_ships[GUNNERY_SHIP_A];
+  struct greyhawk_ship_data *target = &greyhawk_ships[GUNNERY_SHIP_B];
